from pyspark.sql import functions as F


def solve(ledger_entries):
    check = (
        F.when(F.col("transfer_id").isNull(), "no transfer")
        .when(~F.col("entry_type").isin("debit", "credit"), "bad type")
        .when(F.col("amount") < 0, "bad amount")
        .when(~F.col("currency").isin("USD", "EUR", "GBP"), "bad currency")
        .otherwise("ok")
    )
    return ledger_entries.select("entry_id", check.alias("check"))
